set -e
echo "== 环境 =="; node -v; python3 -V; ffmpeg -version | head -1
nproc; free -g | sed -n 2p; df -h / | tail -1
CHROME=$(command -v google-chrome-stable || command -v google-chrome || command -v chromium || true)
echo "chrome=$CHROME"
export CHROME_PATH="$CHROME"

mkdir -p work out && cd work
python3 - <<'PYEOF'
import base64, gzip
FILES = {
    "index.html": "",
    "anim.js": "",
    "data.js": "",
    "frames.js": "",
}
for name, b64 in FILES.items():
    open(name, "wb").write(gzip.decompress(base64.b64decode(b64)))
    print("写回", name, len(open(name, "rb").read()))
PYEOF
npm init -y >/dev/null 2>&1 || true
echo "== npm install puppeteer-core =="
npm install --no-fund --no-audit puppeteer-core@23 2>&1 | tail -2
echo "== 渲染 =="
node frames.js
echo "== 编码 =="
cd ..
ffmpeg -hide_banner -loglevel warning -y -framerate 30 -i work/frames/f%05d.jpg \
  -c:v libx264 -preset medium -crf 19 -pix_fmt yuv420p -movflags +faststart out/tsm_kline.mp4
ls -lh out/
du -sh work/frames || true
